insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', '2 months before', 'Client kick-off email', 'Client partner', 'All events', 'Sent after signing (Fern or Nic). Event overview + upcoming items. Asks client to add marketing materials, register, book hotels. Prompts scheduling of prep, deal strategy, and debrief calls. Includes key links. Note: Beth may fill client partner role — flag for Fern. Action items for client: register for event and book hotel. Include registration and hotel links if available.', 'Comms', 2, 'months', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', '2 months before', 'Collect client to-dos', 'Client partner', 'All events', 'Collect client to-dos before the client kickoff call — the kickoff is where those to-dos get listed and assigned.', 'Client', 2, 'months', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', '6 weeks before', 'Send top 20 target request + EXT attendee list', 'Client partner', 'All events', 'Send the client EXT spreadsheet (initial Informa attendee list). Client marks their top 20 operators to invite to 858 activations. Note: Beth may fill client partner role — flag for Fern. When EXT list is received, update the Google Script with client EXT spreadsheet IDs and start weekly update cadence.', 'Comms', 6, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', 'Day of', 'Create + maintain client external (EXT) spreadsheets', 'Christina', 'All events', 'External Google Sheets with attendee list shared with each client. Refresh weekly as Informa sends updates.', 'Client', 0, 'days', 'on event date', 6, 'weeks', 'before event', 'weekly');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', '4 weeks before', 'Remind clients to schedule all three meetings', 'Client partner', 'All events', 'Optional. By 4 weeks out, three meetings should be scheduled: prep call (2 weeks before), deal strategy call (1 week before), debrief call (1 week after). Remind weekly if not yet confirmed. Timing depends on overall client communication volume.', 'Client', 4, 'weeks', 'before event', NULL, NULL, NULL, 'weekly');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', '3 weeks before', 'Send dossier live email', 'Christina + Client partner', 'All events', 'Includes the Rebrandly dossier link + instructions to complete the prioritization exercise (tier 1/2, current customers, detractors).', 'Comms', 3, 'weeks', 'before event', NULL, NULL, NULL, 'none');
