insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client comms & calls', '2 weeks before', 'Client prep kickoff call', 'Client partner + Nic', 'All events', 'Walks through the prep deck: logistics, expectations, activation format, Q&A. Note: Beth may fill client partner role — flag for Fern.', 'Client', 2, 'weeks', 'before event', NULL, NULL, NULL, 'none');
