insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Invite campaign', '6 weeks before', 'Add client top 20 targets to internal hub', 'TBD', 'All events', 'Add one tab per client to the internal hub with their top 20 target list based on the top 20 target exercise.', 'Internal', 6, 'weeks', 'before event', NULL, NULL, NULL, 'none');
