insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client dossiers', '4 weeks before', 'Create copy for client dossier', 'Christina + Fernando', 'All events', 'Draft all copy for the client dossier page: intro, agenda, team bios, contextual copy. Created before building the dossier page.', 'Content', 4, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client dossiers', '4 weeks before', 'Build client dossier page in Notion', 'Christina', 'All events', 'Build full dossier page including: intro, agenda, copy, team bios, maps, priority targets, full attendee list. One Notion page per client.', 'Content', 4, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Client dossiers', '4 weeks before', 'QA client dossier', 'Christina', 'All events', 'CRITICAL QA before link goes live. Checklist: all links live and working, each client has only their own attendee list (no cross-client data), no spelling errors, all Notion pages published with correct sharing, shareable link confirmed working, client-specific data (buyer intents, GRIP schedule) verified accurate.', 'Content', 4, 'weeks', 'before event', NULL, NULL, NULL, 'none');
