insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '6 weeks before', 'Confirm floor plan + capacity from venue/Informa', 'Fernando', 'Luncheon / Workshop / 858 House', 'Confirm floor capacity, table count, room setup with venue or Informa. Needed even when seating isn''t assigned. Send floor plan and capacity numbers to JG — needed for seating planning and to size the invite campaign.', 'Event logistics', 6, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '8 weeks before', 'Menu preapproval in writing', 'Fernando', 'Luncheon / 858 House / Evening networking', 'Menu reviewed and approved in writing BEFORE venue contract is signed. Espresso required at every daytime 858 event — non-negotiable. Evening social menu also requires approval. Optional.', 'Vendors', 8, 'weeks', 'before event', NULL, NULL, NULL, 'none');
