insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '6 weeks before', 'Furniture rental order', 'Fernando', 'Luncheon / Workshop / 858 House', 'Only if bringing furniture from outside the venue. Lock early — often has the earliest vendor deadline.', 'Vendors', 6, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '4 weeks before', 'Collect tech stand requirements + send to client', 'Christina', 'Presentation', 'Collect all technical requirements for the tech stand and send to the client.', 'Event logistics', 4, 'weeks', 'before event', NULL, NULL, NULL, 'none');
