insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '3 weeks before', 'Confirm AV + tech setup', 'Fernando', 'Luncheon / Workshop / 858 House / Presentation', '858 owns: laptop, HDMI, cables. Purchase and test before event. Never rely on JG''s personal equipment or venue Bluetooth. Confirm microphone/PA for any session with 10+ attendees.', 'Event logistics', 3, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '3 weeks before', 'Confirm Wi-Fi + internet access', 'Fernando', 'Luncheon / Workshop / 858 House / Presentation', 'Confirm venue WiFi credentials and bandwidth for the day. Especially critical for 858 House lounge and any session using live data or real-time tools.', 'Event logistics', 3, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '3 weeks before', 'Hire extra staff', 'Fernando', 'Luncheon / Workshop / 858 House', 'Check-in help, room flips, extra F&B staff as needed. For large-scale events. ESM and brand connector roles evaluated for consolidation.', 'Vendors', 3, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '5 days before', 'Designate music lead + build playlists', 'Fernando', '858 House', 'Assign music lead (owns the board all day — not a playlist on shuffle). Build moment-by-moment playlists: arrival/registration (warm, low BPM), session opens (fade to zero — 8-second rule), breaks (energy lift), networking, close. Download offline — no streaming dependency. 858-owned equipment (Sonos portable or JBL EON).', 'Event logistics', 5, 'days', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '1 week before', 'Vendor parking + load-in/load-out coordination', 'Fernando', 'All events', 'Confirm load-in times, dock access, vendor parking, and load-out schedule for all vendors (espresso, furniture, decor, staffing).', 'Vendors', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '2 weeks before', 'Shipping logistics', 'Fernando + Christina', 'All events', 'Coordinate shipping of swag, signage, badges, and any event materials to the venue. Confirm tracking and delivery confirmation.', 'Vendors', 2, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '1 week before', 'Build run-of-show + designate transition leads', 'Fernando + Christina', 'All events', 'Detailed minute-by-minute schedule. Include: where to be and when, designated transition lead per room (JG is NEVER the transition lead), ESM 5-minute warning protocol, and music cues. Also feeds the photography dossier.', 'Content', 1, 'weeks', 'before event', 2, 'weeks', 'before event', 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '1 day before', 'Venue walkthrough + event rehearsal', 'Fernando', 'All events', 'Physical walkthrough of ALL venues (day + evening). Fern walks everyone through the space. JG practices speeches. AV setups tested. Music tested.', 'Event logistics', 1, 'days', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Vendors & logistics', '2 weeks after', 'Vendor invoice tracking + payment', 'Christina', 'All events', 'Track all outstanding vendor invoices post-event. Flag any that are overdue. Notify Fern to process payments per contract terms.', 'Vendors', 2, 'weeks', 'after event', 1, 'weeks', 'after event', 'none');
