insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 day before', 'Prep workshop room supplies + Granola setup', 'Fernando + Christina', 'Workshop', 'Note cards, pens, name tents per seat, printed discussion prompts at each table. Set up Granola recording device in each room. Confirm furniture and room layout match the floor plan.', 'Event logistics', 1, 'days', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 week before', 'Write + approve sponsor intro scripts', 'Fernando + JG', 'Luncheon', 'JG delivers ALL sponsor introductions (30-second scripted reads). Format: operator problem first, one differentiating line, named customer in the room, named sponsor rep. Sponsors NEVER self-present. Scripts locked by 858 in advance.', 'Content', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '2 weeks before', 'Build + confirm housekeeping slides with client logos', 'Fernando', 'Luncheon', 'Slides shown during remarks with client logos rotating on screen. Confirm screen/monitor availability with venue contact. Confidence monitor also confirmed.', 'Content', 2, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 week before', 'Write + finalize JG opening remarks', 'JG', 'Luncheon / Workshop / Presentation', 'JG drafts opening remarks. Include: how clients are introduced (operator problem first — never self-presented), event framing, and client intro remarks. Multiple review rounds before final.', 'Content', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '4 weeks before', '858 House venue + lounge setup coordination', 'Fernando', '858 House', 'Luxury lounge feel. Full bar, espresso, high-end F&B. Confirm room setup, furniture, and vendor logistics. Confirm lounge hours. Determine if tent needed.', 'Event logistics', 4, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 week before', '858 House check-in + table reservations setup', 'Fernando', '858 House', 'Build check-in system. Clients can reserve tables in advance for prospect meetings. Confirm escort and front-desk check-in staffing.', 'Event logistics', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '4 weeks before', 'Confirm GRIP designate per partner', 'Client partner', 'GRIP Meetings', 'Each partner assigns one person (designator) to log into GRIP and make selections for the company. Each client gets 10 meetings per company even with 2 attendees.', 'Event logistics', 4, 'weeks', 'before event', 6, 'weeks', 'before event', 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '3 weeks before', 'Client completes GRIP operator preference selections (top 40)', 'Client partner', 'GRIP Meetings', 'Designator logs into GRIP and selects up to 40 operators to meet. Cross-reference dossier tier 1/2 to help prioritize. Operators also make selections; GRIP matches on mutual interest.', 'Event logistics', 3, 'weeks', 'before event', 4, 'weeks', 'before event', 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 week before', 'Review preliminary GRIP meeting schedule + flag issues', 'Client partner', 'GRIP Meetings', 'Informa publishes a draft schedule. Review each client''s 10 meetings and flag conflicts or mismatches directly with Informa.', 'Event logistics', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', 'Day of', 'GRIP on-site support + ESM coverage', 'Client partner + ESMs', 'GRIP Meetings', '10 x 10-min back-to-back 1:1s per client. ESMs keep each client on time and equipped, flag no-shows, manage transitions between meetings.', 'Event logistics', 0, 'days', 'on event date', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '2 weeks before', 'Presentation: submit materials to Informa', 'Fernando + JG', 'Presentation', 'Submit presentation deck, speaker bio/headshot, and any supporting materials required by Informa. Confirm submission deadlines with Informa contact. For CREATE: submit Innovation Forum materials per Informa deadline.', 'Content', 2, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 day before', 'Presentation: AV rehearsal + final speaker prep', 'JG + Fernando', 'Presentation', 'JG rehearses the presentation. Test AV, clicker, slide transitions. Confirm confidence monitor. Happens during the venue walkthrough day before.', 'Content', 1, 'days', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '8 weeks before', 'Research + identify guest speaker candidates', 'JG + Fernando', 'Guest speaker', 'JG, Fernando, and Marty identify who they want as outside speaker or guest draw. Fit criteria: relevant to operator audience, credible brand, willing to participate. Build shortlist.', 'Event logistics', 8, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '6 weeks before', 'Outreach to guest speaker candidates', 'Fernando', 'Guest speaker', 'Fern leads outreach to speaker candidates. Confirm interest, availability, format, and any fee or reimbursement expectations. Escalate to JG for any high-profile targets.', 'Event logistics', 6, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '5 weeks before', 'Confirm + sign guest speaker agreement', 'Fernando', 'Guest speaker', 'Sign agreement covering format, session length, travel/hotel reimbursement policy, invoice process, and any usage rights. Confirm speaker is aware this is not a self-promotional slot.', 'Event logistics', 5, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '3 weeks before', 'Guest speaker briefing meeting', 'Fernando + Christina', 'Guest speaker', 'Meet with confirmed speaker to walk through: 858 event format, what their session looks like, how long, who the audience is, what we expect (not a sales pitch), what to expect from attendees, Q&A format.', 'Event logistics', 3, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 week before', 'Collect speaker bio + headshot', 'Christina', 'Guest speaker', 'Collect speaker''s bio, headshot, and preferred contact info. Used in: program guide (speaker spotlight section), post-event recap (guest speaker section), and post-event comms.', 'Event logistics', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '1 week before', 'Send speaker run-of-show, collateral + logistics brief', 'Fernando + Christina', 'Guest speaker', 'Send speaker the run-of-show, all event collateral, and full logistics brief: on-site contact, arrival logistics, hotel booking details.', 'Event logistics', 1, 'weeks', 'before event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Activation operations', '2 weeks after', 'Coordinate speaker travel + hotel invoice reimbursement', 'Fernando', 'Guest speaker', 'Speaker books their own travel and hotel. After the event, collect invoice(s) and process reimbursement per agreement terms. Confirm with Fern on payment timeline.', 'Event logistics', 2, 'weeks', 'after event', NULL, NULL, NULL, 'none');
insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Photography', '8 weeks before', 'Research + vet photographers', 'Christina', 'All events', 'Get 2-3 quotes per city. Review portfolios. Research walk-in headshot options for unregistered attendees. Consider past photographers by city.', 'Vendors', 8, 'weeks', 'before event', NULL, NULL, NULL, 'none');
