insert into library_tasks (workstream,timing,title,owner,applies_to,notes,task_type,due_amount,due_unit,due_ref,start_amount,start_unit,start_ref,recurrence) values ('Photography', '6 weeks before', 'Pay photography deposit', 'Fernando + Christina', 'All events', 'Pay deposit per contract terms immediately upon signing.', 'Vendors', 6, 'weeks', 'before event', NULL, NULL, NULL, 'none');
